const int PWMA = 5, AIN1 = 7, AIN2 = 8, STBY = 9;

void setup() {
  pinMode(PWMA, OUTPUT); pinMode(AIN1, OUTPUT); pinMode(AIN2, OUTPUT); pinMode(STBY, OUTPUT);
  digitalWrite(STBY, HIGH);
  Serial.begin(9600);
}

void loop() {
  // this drives forward at the first step only: add the other four, the brake and the reverse sweep
  digitalWrite(AIN1, HIGH); digitalWrite(AIN2, LOW);
  analogWrite(PWMA, 51);
  delay(1000);
}

